// Bitrix outbound webhook gövdesini çözer (urlencoded hem iç içe hem düz anahtar gelebilir)
const ayar = $('Ayarlar').first().json;
const b = $input.first().json.body || {};
const event = String(b.event || '').toUpperCase();
const id = (b.data && b.data.FIELDS && b.data.FIELDS.ID) || b['data[FIELDS][ID]'];
const token = (b.auth && b.auth.application_token) || b['auth[application_token]'];

if (event !== 'ONCRMLEADADD' || !id) return [];
if (ayar.bitrixAppToken && ayar.bitrixAppToken !== 'BURAYA_GIDEN_WEBHOOK_TOKEN' && token !== ayar.bitrixAppToken) {
  throw new Error('Geçersiz Bitrix application_token');
}
return [{ json: { leadId: String(id), bitrixUrl: ayar.bitrixWebhookUrl.replace(/\/?$/, '/') } }];

// Form ID -> Telegram grubu eşlemesi
const FORMS = {
  206: { ad: '10 MELTEM EFAS FORM',        chatId: '-5106515364', anahtar: ['MELTEM'] },
  208: { ad: '11 BURCU EFAS FORM',         chatId: '-5454384941', anahtar: ['BURCU'] },
  210: { ad: '12 CAFER EFAS FORM',         chatId: '-5440932746', anahtar: ['CAFER'] },
  212: { ad: '13 MUSTAFA UTKU EFAS FORM',  chatId: '-5451627345', anahtar: ['MUSTAFA UTKU'] },
  214: { ad: '14 MUSTAFA ALTAY EFAS FORM', chatId: '-5250586334', anahtar: ['MUSTAFA ALTAY'] },
  216: { ad: '15 MURAT ER EFAS FORM',      chatId: '-5483964717', anahtar: ['MURAT ER'] },
  218: { ad: '16 BERKCAN KARTAL EFAS FORM',chatId: '-5297361374', anahtar: ['BERKCAN'] },
  220: { ad: '17 FATIH EFAS FORM',         chatId: '-5104387991', anahtar: ['FATIH'] },
  222: { ad: '18 DEMET EFAS FORM',         chatId: '-5300073899', anahtar: ['DEMET'] },
  224: { ad: '19 TIMUCIN FORM',            chatId: '-5332587759', anahtar: ['TIMUCIN'] },
};

const norm = s => String(s || '').toLocaleUpperCase('tr-TR')
  .replace(/İ/g, 'I').replace(/I/g, 'I').replace(/Ş/g, 'S').replace(/Ğ/g, 'G')
  .replace(/Ü/g, 'U').replace(/Ö/g, 'O').replace(/Ç/g, 'C').replace(/\s+/g, ' ');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lead = $('Lead Getir').first().json.result || {};
const acts = $('Form Aktivitesi Getir').first().json.result || [];

// 1) Kesin yol: CRM_WEBFORM aktivitesinden form ID
let formId = null, formAdi = '';
for (const a of acts) {
  const p = a.PROVIDER_PARAMS || {};
  const fid = Number(p.FORM_ID || a.ASSOCIATED_ENTITY_ID);
  if (FORMS[fid]) { formId = fid; formAdi = a.SUBJECT || ''; break; }
}

// 2) Yedek yol: başlık / kaynak açıklaması / aktivite konusu içinde isim ara
if (!formId) {
  const metin = norm([lead.TITLE, lead.SOURCE_DESCRIPTION, lead.COMMENTS, ...acts.map(a => a.SUBJECT)].join(' | '));
  for (const [fid, f] of Object.entries(FORMS)) {
    if (f.anahtar.some(k => metin.includes(k))) { formId = Number(fid); break; }
  }
}

if (!formId) return []; // EFAS formu değil -> sessizce dur

const f = FORMS[formId];
const ad = [lead.NAME, lead.SECOND_NAME, lead.LAST_NAME].filter(Boolean).join(' ') || lead.TITLE || '-';
const tel = (lead.PHONE || []).map(p => p.VALUE).join(', ') || '-';
const mail = (lead.EMAIL || []).map(e => e.VALUE).join(', ') || '';
const portal = $('Ayarlar').first().json.bitrixPortalUrl.replace(/\/$/, '');
const tarih = new Date(lead.DATE_CREATE || Date.now()).toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

const satirlar = [
  '🔔 <b>Yeni Form Başvurusu</b>',
  '',
  `📋 <b>Form:</b> ${esc(formAdi || f.ad)} (ID ${formId})`,
  `👤 <b>Ad Soyad:</b> ${esc(ad)}`,
  `📞 <b>Telefon:</b> ${esc(tel)}`,
];
if (mail) satirlar.push(`✉️ <b>E-posta:</b> ${esc(mail)}`);
if (lead.COMMENTS) satirlar.push(`📝 <b>Not:</b> ${esc(String(lead.COMMENTS).replace(/<[^>]+>/g, ' ').slice(0, 500))}`);
satirlar.push(`🕒 <b>Tarih:</b> ${esc(tarih)}`);
satirlar.push(`🔗 <a href="${portal}/crm/lead/details/${lead.ID}/">Bitrix'te aç (Lead #${lead.ID})</a>`);

return [{ json: { chatId: f.chatId, formId, leadId: lead.ID, text: satirlar.join('\n') } }];
